/**
 * Independent, fictional usage traces. No production imports or classifier thresholds.
 * Oracle annotations are evaluation-only context; only `trace` may reach a model.
 * Expected values were calculated from the scripted intervals, not generated by replay.
 */

const availability = (at, feed = 'supported', input = 'available', visibility = 'visible') => ({
    at, type: 'availability', feed, input, visibility,
});
const advance = (at, screenfuls = 1, itemTransitions = 1, source = 'user') => ({
    at, type: 'feed_advance', screenfuls, itemTransitions, source,
});
const input = (at, mode = 'typing') => ({ at, type: 'input', mode });
const exposure = (at, active) => ({ at, type: 'intervention', active });
const repeatedInput = (firstAt, count, spacingMs, mode = 'typing') => Array.from(
    { length: count }, (_, index) => input(firstAt + index * spacingMs, mode),
);
const trace = (endMs, events) => ({
    startMs: 0,
    endMs,
    initialInterventionActive: false,
    events: events.toSorted((left, right) => left.at - right.at),
});
const oracle = (fictionalIntent, rationale, permittedConclusions, abstainOn) => ({
    fictionalIntent,
    rationale,
    permittedConclusions,
    prohibitedConclusions: [
        'Input-event count establishes characters, words, writing speed, or time spent writing.',
        'Document visibility establishes attention, reading, or comprehension.',
        'A feed progression rate by itself establishes unwanted or intentional use.',
        'An intervention exposure proves the preceding behavior warranted intervention.',
        'Unavailable or unsupported observation establishes zero activity.',
    ],
    abstainOn,
});

const repeatedReactionEvents = () => [
    availability(0),
    ...Array.from({ length: 12 }, (_, index) => [
        advance(index * 20_000 + 1_000, 1, 2),
        input(index * 20_000 + 3_000),
        input(index * 20_000 + 4_000),
        input(index * 20_000 + 5_000),
    ]).flat(),
];

